package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class CSVPrinter_CSVPrinter_TriageGen1Test {

    @Test
    public void testConstructorValidParameters() throws IOException {
        Appendable out = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT;

        CSVPrinter printer = new CSVPrinter(out, format);

        assertEquals(out, printer.getOut());
        printer.close();
    }

    @Test(expected = NullPointerException.class)
    public void testConstructorNullOut() throws IOException {
        CSVFormat format = CSVFormat.DEFAULT;
        new CSVPrinter(null, format);
    }

    @Test(expected = NullPointerException.class)
    public void testConstructorNullFormat() throws IOException {
        Appendable out = new StringWriter();
        new CSVPrinter(out, null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testConstructorInvalidFormat() throws IOException {
        Appendable out = new StringWriter();
        // Creating an invalid format that throws exception during validate()
        // CSVFormat is immutable, so we simulate an invalid state if possible 
        // or use a known edge case if the library allows.
        // Since we cannot easily force validate() to fail without internal access, 
        // we assume a format that violates constraints would be passed.
        // For the purpose of coverage on the format.validate() line:
        CSVFormat invalidFormat = new CSVFormat.Builder()
                .setDelimiter(null) // This should trigger validation error in validate()
                .build();

        new CSVPrinter(out, invalidFormat);
    }
}
